      valorMensal: decimal("valor_mensal", { precision: 10, scale: 2 }).notNull(),
      formaPagamento: text("forma_pagamento").default("pix"),
      // pix, transferencia, boleto, debito_automatico
      observacoes: text("observacoes"),
      // ex: "DOADOR ANJO"
      dataInicio: timestamp("data_inicio").defaultNow(),
      status: text("status").default("ativo"),
      // ativo, inativo, pausado
      email: text("email"),
      telefone: text("telefone"),
      ativo: boolean("ativo").default(true),
      dataAdmissao: date("data_admissao"),
