      missaoId: integer("missao_id").references(() => missoesSemanais.id).notNull(),
      status: text("status").default("pendente_validacao"),
      // 'pendente_validacao', 'aprovado', 'reprovado', 'expirado'
      evidenceType: text("evidence_type").notNull(),
