import pkg from "pg";
import { drizzle } from "drizzle-orm/node-postgres";
async function testDatabaseConnection(retries = 3) {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      console.log(`\u{1F504} [DB_*] Tentativa ${attempt}/${retries}...`);
      const client = await pool.connect();
      const result = await client.query("SELECT current_database() as db_name");
      client.release();
      console.log(`\u2705 [DB_*] Conectado: ${result.rows[0]?.db_name}`);
      return true;
    } catch (error) {
      console.error(
        `\u274C [DB_*] Tentativa ${attempt} falhou:`,
        error instanceof Error ? error.message : error
      );
      if (attempt < retries) await new Promise((r) => setTimeout(r, 2e3));
    }
  }
  throw new Error("\u274C Falha ao conectar no banco (DB_*) ap\xF3s tentativas.");
}
async function runAutoMigrations() {
  try {
    console.log("\u{1F504} Verificando migra\xE7\xF5es pendentes...");
    await pool.query(`
      ALTER TABLE monitor_grupos 
      ADD COLUMN IF NOT EXISTS horario_inicio TEXT,
      ADD COLUMN IF NOT EXISTS horario_fim TEXT,
      ADD COLUMN IF NOT EXISTS dias_semana TEXT[];
    `);
    console.log("\u2705 Migra\xE7\xF5es autom\xE1ticas conclu\xEDdas");
  } catch (error) {
    console.error(
      "\u26A0\uFE0F Erro nas migra\xE7\xF5es autom\xE1ticas (pode ser ignorado se colunas j\xE1 existem):",
      error instanceof Error ? error.message : error
    );
  }
}
