      async getAttendanceReportByProfessor(professorId, classId, date2) {
        try {
          const conditions = [eq(chamada2.professorId, professorId)];
          if (classId) {
            conditions.push(eq(chamada2.turmaId, classId));
          }
          if (date2) {
            conditions.push(eq(chamada2.data, date2));
          }
          const result = await db.select().from(chamadaAluno2).innerJoin(chamada2, eq(chamadaAluno2.chamadaId, chamada2.id)).innerJoin(aluno, eq(chamadaAluno2.alunoCpf, aluno.cpf)).where(and(...conditions));
          return result.map((item) => ({
            student_name: item.aluno.nome_completo,
            status: item.chamada_aluno.status,
            observacoes: item.chamada_aluno.observacoes,
            date: item.chamada.data
          }));
        } catch (error) {
          console.error("Error fetching attendance report:", error);
          return [];
        }
      }
