function registerPecImportRoutes(app2, storage2) {
  app2.post("/api/pec/import/alunos/preview", upload.single("file"), async (req, res) => {
    try {
      if (!req.file?.buffer) return res.status(400).json({ error: "Arquivo n\xE3o enviado" });
      const wb = XLSX2.read(req.file.buffer, { type: "buffer" });
      const sheetName = wb.SheetNames[0];
      const ws = wb.Sheets[sheetName];
      const rows = XLSX2.utils.sheet_to_json(ws, { defval: "" });
      const results = rows.map((row, idx) => {
        const rowNumber = idx + 2;
        const { payload, extraErrors } = rowToAlunoPayload(row);
        const parsed = alunoImportSchema.safeParse(payload);
        const errors = [];
        if (!parsed.success) {
          parsed.error.issues.forEach((iss) => {
            errors.push({ field: String(iss.path?.[0] ?? "geral"), message: iss.message });
          });
        }
        extraErrors.forEach((e) => errors.push(e));
        return {
          rowNumber,
          cpf: payload.cpf,
          nome_completo: payload.nome_completo,
          ok: errors.length === 0,
          errors,
          payload
          // já pronto pro commit
        };
      });
      const cpfCount = /* @__PURE__ */ new Map();
      results.forEach((r) => {
        if (!r.cpf) return;
        cpfCount.set(r.cpf, (cpfCount.get(r.cpf) ?? 0) + 1);
      });
      results.forEach((r) => {
        if (r.cpf && (cpfCount.get(r.cpf) ?? 0) > 1) {
          r.ok = false;
          r.errors.push({ field: "cpf", message: "CPF duplicado dentro da planilha" });
        }
      });
      const summary = {
        total: results.length,
        valid: results.filter((r) => r.ok).length,
        invalid: results.filter((r) => !r.ok).length
      };
      res.json({ summary, results });
    } catch (err) {
      console.error("PEC import preview error:", err);
      res.status(500).json({ error: "Falha ao processar planilha" });
    }
  });
  app2.post("/api/pec/import/alunos/commit", async (req, res) => {
    try {
      const { rows } = req.body;
      if (!Array.isArray(rows) || rows.length === 0) {
        return res.status(400).json({ error: "Nenhuma linha enviada para importa\xE7\xE3o" });
      }
      const inserted = [];
      const skipped = [];
      const failed = [];
      for (const r of rows) {
        const payload = { ...r.payload ?? {}, area: "pec" };
        const parsed = alunoImportSchema.safeParse(payload);
        if (!parsed.success) {
          failed.push({
            rowNumber: r.rowNumber,
            cpf: payload.cpf,
            nome_completo: payload.nome_completo,
            error: parsed.error.issues.map((i) => ({ field: i.path?.[0], message: i.message }))
          });
          continue;
        }
        const exists = await storage2.getAluno(payload.cpf);
        if (exists) {
          skipped.push({ rowNumber: r.rowNumber, cpf: payload.cpf, reason: "CPF j\xE1 existe no banco" });
          continue;
        }
        try {
          if (payload.telefone && payload.nome_completo) {
            const { consolidateUser: consolidateUser2 } = await import("./userConsolidation");
            await consolidateUser2({
              nome: payload.nome_completo,
              telefone: payload.telefone,
              email: payload.email,
              cpf: payload.cpf,
              tipo: "aluno",
              fonte: "educacao"
            });
          }
        } catch (e) {
          console.error("Erro na consolida\xE7\xE3o (import):", e);
        }
        try {
          const aluno2 = await storage2.createAluno(payload);
          inserted.push({ rowNumber: r.rowNumber, cpf: payload.cpf, id: aluno2?.id ?? null });
        } catch (e) {
          failed.push({ rowNumber: r.rowNumber, cpf: payload.cpf, error: e?.message ?? "Falha ao inserir" });
        }
      }
      res.json({
        summary: {
          requested: rows.length,
          inserted: inserted.length,
          skipped: skipped.length,
          failed: failed.length
        },
        inserted,
        skipped,
        failed
      });
    } catch (err) {
      console.error("PEC import commit error:", err);
      res.status(500).json({ error: "Falha ao importar alunos" });
    }
  });
}

