  app2.get("/api/subscription/verify", async (req, res) => {
    try {
      const phone = req.query.phone;
      if (!phone) {
        return res.status(400).json({ error: "Telefone \xE9 obrigat\xF3rio" });
      }
      console.log(
        `\u{1F50D} [VERIFY-SUB] Verificando assinatura para telefone: ${phone}`
      );
      const variants = getPhoneSearchVariants(phone);
      let customers = null;
      for (const v of variants) {
        const result = await stripe2.customers.search({
          query: `phone~"${v}"`,
          limit: 10
        });
        if (result.data.length) {
          customers = result;
          break;
        }
      }
      if (!customers || !customers.data.length) {
        console.log(`\u26A0\uFE0F [VERIFY-SUB] Nenhum cliente encontrado para ${phone}`);
        return res.json({
          hasActiveSubscription: false,
          reason: "customer_not_found"
        });
      }
      let bestNonActive = null;
      for (const customer2 of customers.data) {
        const best = await findBestActiveSubscription(stripe2, customer2.id);
        if (best.ok && best.sub) {
          return res.json({
            hasActiveSubscription: true,
            subscriptionId: best.sub.id,
            status: best.sub.status,
            customerId: customer2.id,
            customerName: customer2.name
          });
        }
        if (best.sub) {
          if (best.sub.status === "incomplete") {
            try {
              await stripe2.subscriptions.cancel(best.sub.id);
              console.log(
                `\u2705 [VERIFY-SUB] Subscription incompleta ${best.sub.id} cancelada`
              );
            } catch (e) {
              console.log(
                `\u26A0\uFE0F [VERIFY-SUB] Falha ao cancelar incomplete: ${e.message}`
              );
            }
            bestNonActive = {
              sub: best.sub,
              customer: customer2,
              reason: "incomplete_subscription_cleared",
              message: "Sua doa\xE7\xE3o anterior n\xE3o foi conclu\xEDda. Por favor, fa\xE7a uma nova doa\xE7\xE3o."
            };
            continue;
          }
          bestNonActive = {
            sub: best.sub,
            customer: customer2,
            reason: `subscription_${best.sub.status}`,
            isPaused: ["past_due", "unpaid"].includes(best.sub.status)
          };
          continue;
        }
      }
      if (bestNonActive) {
        return res.json({
          hasActiveSubscription: false,
          isPaused: bestNonActive.isPaused ?? false,
          subscriptionId: bestNonActive.sub.id,
          status: bestNonActive.sub.status,
          customerId: bestNonActive.customer.id,
          customerName: bestNonActive.customer.name,
          reason: bestNonActive.reason,
          message: bestNonActive.message
        });
      }
      console.log(
        `\u26A0\uFE0F [VERIFY-SUB] Nenhuma assinatura encontrada para ${phone}`
      );
      return res.json({
        hasActiveSubscription: false,
        reason: "no_subscription_found"
      });
    } catch (error) {
      console.error("\u274C [VERIFY-SUB] Erro:", error?.message || error);
      return res.status(500).json({
        error: "Erro ao verificar assinatura",
        message: error?.message || String(error)
      });
    }
  });
  app2.get("/api/subscriptions/:id/client-secret", async (req, res) => {
    try {
      const subscriptionId = req.params.id;
      console.log(
        `\u{1F50D} [POLLING] Buscando client_secret para subscription: ${subscriptionId}`
      );
      const subscription = await stripe2.subscriptions.retrieve(subscriptionId, {
        expand: ["latest_invoice.payment_intent", "pending_setup_intent"]
      });
      const invoice = subscription.latest_invoice;
      const paymentIntent = invoice?.payment_intent;
      let setupIntent = subscription.pending_setup_intent;
      const customerId = subscription.customer;
      let secretType = null;
      let clientSecret = null;
      if (paymentIntent?.client_secret) {
        secretType = "payment";
        clientSecret = paymentIntent.client_secret;
        console.log(
          `\u2705 [POLLING] PaymentIntent encontrado: ${paymentIntent.id}`
        );
      } else if (setupIntent) {
        const setupIntentFull = await stripe2.setupIntents.retrieve(
          setupIntent
        );
        secretType = "setup";
        clientSecret = setupIntentFull.client_secret;
        console.log(
          `\u2705 [POLLING] SetupIntent encontrado (autom\xE1tico): ${setupIntent}`
        );
      } else if (!paymentIntent && !setupIntent) {
        console.log(
          `\u26A0\uFE0F [POLLING] Nenhum PaymentIntent/SetupIntent encontrado - criando SetupIntent manualmente...`
        );
        const newSetupIntent = await stripe2.setupIntents.create({
          customer: stripeCustomerId,
          payment_method_types: ["card"],
          usage: "off_session",
          metadata: {
            subscriptionId: subscription.id,
            invoiceId: invoice?.id || ""
          }
        });
        setupIntent = newSetupIntent.id;
        secretType = "setup";
        clientSecret = newSetupIntent.client_secret;
        console.log(
          `\u2705 [POLLING] SetupIntent criado manualmente: ${newSetupIntent.id}`
        );
      }
      if (!clientSecret) {
        console.log(
          `\u23F3 [POLLING] ClientSecret ainda n\xE3o dispon\xEDvel para subscription ${subscriptionId}`
        );
        return res.status(202).json({
          status: "processing",
          message: "Secret ainda est\xE1 sendo gerado. Tente novamente em 1 segundo.",
          subscriptionStatus: subscription.status
        });
      }
      console.log(`\u2705 [POLLING] ClientSecret encontrado (tipo: ${secretType})`);
      res.json({
        secretType,
        clientSecret,
        paymentIntentId: paymentIntent?.id || null,
        setupIntentId: setupIntent || null,
        invoiceId: invoice?.id || null,
        subscriptionStatus: subscription.status
      });
    } catch (error) {
      console.error(
        "\u274C [POLLING] Erro ao buscar client_secret:",
        error.message
      );
      res.status(500).json({
        error: "Erro ao buscar informa\xE7\xF5es da subscription",
        message: error.message
      });
    }
  });
