  async function consultarTransacaoCieloEcommerce(paymentId) {
    try {
      const merchantId = process.env.MERCHANT_ID_CIELO;
      const merchantKey = process.env.MERCHANT_KEY_CIELO;
      if (!merchantId || !merchantKey) {
        console.error("\u274C [CIELO] Credenciais n\xE3o configuradas");
        return null;
      }
      const url = `https://apiquery.cieloecommerce.cielo.com.br/1/sales/${paymentId}`;
      const response = await fetch(url, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          MerchantId: merchantId,
          MerchantKey: merchantKey
        }
      });
      if (!response.ok) {
        if (response.status === 404) {
          return null;
        }
        const errorText = await response.text();
        console.error(
          `\u274C [CIELO QUERY] Erro HTTP ${response.status} para PaymentId ${paymentId}: ${errorText}`
        );
        return null;
      }
      const data = await response.json();
      return data;
    } catch (error) {
      console.error(
        `\u274C [CIELO QUERY] Erro ao consultar transa\xE7\xE3o ${paymentId}:`,
        error
      );
      return null;
    }
  }
  app2.post(
    "/api/admin/cielo/atualizar-status-manual",
    requireAuth,
    requireAdmin,
    async (req, res) => {
      try {
        const { ingressoIds, novoStatus } = req.body;
        if (!ingressoIds || !Array.isArray(ingressoIds) || ingressoIds.length === 0) {
          return res.status(400).json({
            success: false,
            error: "IDs de ingressos inv\xE1lidos"
          });
        }
        if (!["confirmado", "cancelado", "negado"].includes(novoStatus)) {
          return res.status(400).json({
            success: false,
            error: "Status inv\xE1lido. Use: confirmado, cancelado ou negado"
          });
        }
        console.log(
          `\u{1F504} [CIELO MANUAL] Atualizando ${ingressoIds.length} ingressos para status: ${novoStatus}`
        );
        await db.update(ingressos).set({ status: novoStatus }).where(
          and3(
            inArray3(ingressos.id, ingressoIds),
            eq6(ingressos.gateway, "cielo_checkout_link")
          )
        );
        console.log(
          `\u2705 [CIELO MANUAL] ${ingressoIds.length} ingressos atualizados`
        );
        res.json({
          success: true,
          atualizados: ingressoIds.length,
          novoStatus
        });
      } catch (error) {
        console.error("\u274C [CIELO MANUAL] Erro:", error);
        res.status(500).json({ success: false, error: "Erro ao atualizar status" });
      }
    }
  );
