  async function processAutomations(event) {
    const automations = await db.select().from(gritoAutomations).where(
      and3(
        eq6(gritoAutomations.matchEvent, event.eventName),
        eq6(gritoAutomations.isActive, true)
      )
    );
    for (const automation of automations) {
      try {
        if (automation.conditionSql) {
          const conditionQuery = automation.conditionSql.replace(
            /\{\{payload\.(\w+)\}\}/g,
            (_, key2) => {
              const value = event.payload?.[key2];
              return typeof value === "string" ? `'${value}'` : String(value);
            }
          );
          const conditionResult = await db.execute(
            sql4.raw(`SELECT EXISTS(${conditionQuery}) as meets_condition`)
          );
          if (!conditionResult.rows[0]?.meets_condition) {
            console.log(
              `\u23ED\uFE0F [AUTOMATION SKIP] ${automation.name}: condi\xE7\xE3o n\xE3o atendida`
            );
            continue;
          }
        }
        if (automation.action.type === "email") {
          const to = automation.action.to?.replace(
            /\{\{payload\.(\w+)\}\}/g,
            (_, key2) => {
              return event.payload?.[key2] || "";
            }
          );
          const variables = { ...automation.action.variables };
          for (const [key2, value] of Object.entries(variables)) {
            variables[key2] = value.replace(
              /\{\{payload\.(\w+)\}\}/g,
              (_, payloadKey) => {
                return event.payload?.[payloadKey] || "";
              }
            );
          }
          await emailService.send(
            automation.action.template_id,
            to,
            variables
          );
          console.log(
            `\u{1F4E7} [AUTOMATION EMAIL] ${automation.name} enviado para ${to}`
          );
        } else if (automation.action.type === "webhook") {
          const subscription = await db.select().from(gritoWebhookSubscriptions).where(
            eq6(
              gritoWebhookSubscriptions.destinationName,
              automation.action.endpoint_ref
            )
          ).limit(1);
          if (subscription[0]) {
            await db.insert(gritoWebhookDeliveries).values({
              eventId: event.id,
              subscriptionId: subscription[0].id,
              status: "PENDING",
              nextAttemptAt: /* @__PURE__ */ new Date()
            });
            console.log(
              `\u{1F517} [AUTOMATION WEBHOOK] ${automation.name} \u2192 ${automation.action.endpoint_ref}`
            );
          }
        }
      } catch (error) {
        console.error(`\u274C [AUTOMATION ERROR] ${automation.name}:`, error);
      }
    }
  }
